/**
 * Filter state lives on <html> as data-tag / data-touch. CSS generated by the page does
 * the hiding, so this module only flips attributes and keeps a11y state in sync.
 */

export interface FilterState {
  tag: string;
  touch: boolean;
}

/**
 * Wraps a filter change in an animation (FLIP). Registered by the motion layer.
 * `willShow` says which items are visible after `change()` runs.
 */
export type FilterAnimator = (change: () => void, willShow: (item: HTMLElement) => boolean) => void;

let animator: FilterAnimator | null = null;

export function setFilterAnimator(fn: FilterAnimator | null): void {
  animator = fn;
}

/** Parse `/tag/<tag>/` or `?tag=&touch=1`, accepting only tags that exist on the page. */
export function readUrlState(
  url: Pick<Location, 'pathname' | 'search'>,
  root: HTMLElement,
): FilterState {
  const params = new URLSearchParams(url.search);
  const fromPath = /^\/tag\/([^/]+)\/?$/.exec(url.pathname)?.[1] ?? '';
  const tag = params.get('tag') ?? decodeURIComponent(fromPath);
  const known = root.querySelector(`a[data-tag="${CSS.escape(tag)}"]`) !== null;
  return { tag: tag && known ? tag : '', touch: params.get('touch') === '1' };
}

export function matches(item: HTMLElement, state: FilterState): boolean {
  if (item.classList.contains('ghost')) return !state.tag && !state.touch;
  const tags = (item.dataset.tags ?? '').split(' ');
  return (
    (!state.tag || tags.includes(state.tag)) && (!state.touch || item.hasAttribute('data-touch'))
  );
}

export function applyFilter(state: FilterState, { announce = true } = {}): void {
  const root = document.documentElement;
  const change = () => {
    if (state.tag) root.dataset.tag = state.tag;
    else delete root.dataset.tag;
    root.toggleAttribute('data-touch', state.touch);
  };
  if (animator && announce) animator(change, (item) => matches(item, state));
  else change();

  for (const chip of document.querySelectorAll<HTMLElement>('.chip[data-tag]')) {
    if ((chip.dataset.tag ?? '') === state.tag) chip.setAttribute('aria-current', 'true');
    else chip.removeAttribute('aria-current');
  }
  document.querySelector('[data-touch-toggle]')?.setAttribute('aria-pressed', String(state.touch));

  const games = [...document.querySelectorAll<HTMLElement>('.card-item:not(.ghost)')];
  const visible = games.filter((item) => matches(item, state)).length;
  const count = document.querySelector('[data-count]');
  const countLabel = document.querySelector('[data-count-label]');
  if (count) count.textContent = String(visible);
  if (countLabel) countLabel.textContent = visible === 1 ? 'game' : 'games';
  const empty = document.querySelector<HTMLElement>('[data-empty]');
  if (empty) empty.hidden = visible > 0;
  const status = document.querySelector('[data-status]');
  if (status && announce) {
    const what = [state.tag && `tagged ${state.tag}`, state.touch && 'that work with touch']
      .filter(Boolean)
      .join(' and ');
    status.textContent = `Showing ${visible} ${visible === 1 ? 'game' : 'games'}${what ? ` ${what}` : ''}.`;
  }
}
